/**
 * svg-cap2.js
 * Thư viện sinh hình học trực quan vector SVG chuẩn môn Toán Cấp 2
 * Khớp chính xác với hình vẽ trong bản thiết kế mockup
 */

export const svgCap2 = {
  svgGrade7Batch4,
  svgGrade7Batch3,
  svgGrade7DataExtension,
  svgGrade7AngleExtension,
  svgGrade6VisualExtension,
  svgGrade6DataExtension,
  svgGrade6GeometryExtension,
  svgGrade8DataCharts,
  svgGrade8Pyramid,
  svgGrade8ScaleGrid,
  svgGrade8PyramidNets,
  svgGrade8Geometry,
  svgGrade8LinearPlot,
  svgGrade6Statistics,
  svgGrade6Models,
  svgGrade6Basics,
  svgGrade6Areas,
  svgGrade6Visual,
  svgGrade6NumberLine,
  svgGrade6FractionBar,
  svgLineChart,
  svgPieChart,
  svgPrismModel,
  svgMeasurementRuler,
  svgProtractor,
  svgRealNumberLine,
  svgGeometry,
  /**
   * Đồ thị hàm số bậc nhất y = ax + b trên hệ trục Oxy
   * Khớp 100% với hình vẽ trong mockup
   */
  svgLinearGraph(config = {}) {
    const w = 460;
    const h = 200;
    const ox = 200;
    const oy = 145;

    // Vạch chia số 2 trên trục Ox: x = 290
    const gx2 = 290;
    // Vạch chia y = 3 trên Oy: y = 65 (hoặc đỉnh gióng)
    const gy3 = 65;
    // Tung độ cắt trục Oy: y = 105
    const gyCut = 105;

    return `<svg class="math-svg" viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="Đồ thị hàm số y = ax + b">
      <defs>
        <!-- Lưới nền nhạt -->
        <pattern id="graph-grid" width="20" height="15" patternUnits="userSpaceOnUse">
          <path d="M 20 0 L 0 0 0 15" fill="none" stroke="#e2e8f0" stroke-width="0.8"/>
        </pattern>
        <marker id="axis-arrow" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
          <path d="M 0 1.5 L 10 5 L 0 8.5 z" fill="#1e293b"/>
        </marker>
      </defs>

      <!-- Nền khung đồ thị bo tròn -->
      <rect width="${w}" height="${h}" rx="10" fill="#f0f5fa"/>
      <rect width="${w}" height="${h}" fill="url(#graph-grid)" rx="10"/>

      <!-- Trục hoành Ox -->
      <line x1="25" y1="${oy}" x2="${w - 25}" y2="${oy}" stroke="#1e293b" stroke-width="1.8" marker-end="url(#axis-arrow)"/>
      <text x="${w - 20}" y="${oy - 4}" font-size="13" font-weight="bold" font-style="italic" fill="#0f172a">x</text>

      <!-- Trục tung Oy -->
      <line x1="${ox}" y1="${h - 15}" x2="${ox}" y2="15" stroke="#1e293b" stroke-width="1.8" marker-end="url(#axis-arrow)"/>
      <text x="${ox - 15}" y="20" font-size="13" font-weight="bold" font-style="italic" fill="#0f172a">y</text>

      <!-- Gốc tọa độ 0 -->
      <text x="${ox - 14}" y="${oy + 15}" font-size="12" font-weight="bold" fill="#0f172a">0</text>

      <!-- Vạch chia số 2 trên trục Ox -->
      <line x1="${gx2}" y1="${oy - 4}" x2="${gx2}" y2="${oy + 4}" stroke="#1e293b" stroke-width="1.5"/>
      <text x="${gx2}" y="${oy + 16}" font-size="12" font-weight="bold" fill="#0f172a" text-anchor="middle">2</text>

      <!-- Vạch chia số 3 trên trục Oy -->
      <line x1="${ox - 4}" y1="${gy3}" x2="${ox + 4}" y2="${gy3}" stroke="#1e293b" stroke-width="1.5"/>
      <text x="${ox - 12}" y="${gy3 + 4}" font-size="12" font-weight="bold" fill="#0f172a" text-anchor="middle">3</text>

      <!-- Vạch chia tại tung độ cắt -->
      <line x1="${ox - 4}" y1="${gyCut}" x2="${ox + 4}" y2="${gyCut}" stroke="#1e293b" stroke-width="1.5"/>
      <text x="${ox - 12}" y="${gyCut + 4}" font-size="12" font-weight="bold" fill="#0f172a" text-anchor="middle">3</text>

      <!-- Đường gióng nét đứt tại (2, y) -->
      <line x1="${gx2}" y1="${oy}" x2="${gx2}" y2="${gy3}" stroke="#64748b" stroke-width="1.5" stroke-dasharray="3 3"/>
      <line x1="${ox}" y1="${gy3}" x2="${gx2}" y2="${gy3}" stroke="#64748b" stroke-width="1.5" stroke-dasharray="3 3"/>

      <!-- Đường thẳng y = ax + b -->
      <line x1="70" y1="163" x2="380" y2="25" stroke="#2563eb" stroke-width="2.6" stroke-linecap="round"/>
    </svg>`;
  },

  /**
   * Đồ thị Parabol y = ax^2
   */
  svgParabolaGraph(a = 1) {
    const w = 460, h = 200, ox = 230, oy = 160, scaleX = 35, scaleY = 28;
    let pathD = `M ${ox - 2.8 * scaleX} ${oy - a * Math.pow(2.8, 2) * scaleY}`;
    for (let x = -2.7; x <= 2.8; x += 0.2) {
      const y = a * Math.pow(x, 2);
      pathD += ` L ${ox + x * scaleX} ${oy - y * scaleY}`;
    }

    return `<svg class="math-svg" viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="Đồ thị Parabol">
      <rect width="${w}" height="${h}" rx="10" fill="#f1f5f9"/>
      <line x1="30" y1="${oy}" x2="${w - 30}" y2="${oy}" stroke="#1e293b" stroke-width="1.8"/>
      <line x1="${ox}" y1="${h - 20}" x2="${ox}" y2="20" stroke="#1e293b" stroke-width="1.8"/>
      <text x="${w - 24}" y="${oy - 6}" font-size="13" font-weight="bold" font-style="italic">x</text>
      <text x="${ox - 15}" y="24" font-size="13" font-weight="bold" font-style="italic">y</text>
      <text x="${ox - 14}" y="${oy + 16}" font-size="12" font-weight="bold">0</text>
      <path d="${pathD}" fill="none" stroke="#0284c7" stroke-width="2.6" stroke-linecap="round"/>
      <text x="${ox + 60}" y="45" font-size="13" font-weight="bold" fill="#0369a1">y = ${a !== 1 ? a : ''}x²</text>
    </svg>`;
  },

  /**
   * Định lí Thales trong tam giác ABC
   */
  svgThalesTriangle() {
    return `<svg class="math-svg" viewBox="0 0 460 200" width="100%" role="img" aria-label="Định lí Thales">
      <rect width="460" height="200" rx="10" fill="#f1f5f9"/>
      <polygon points="230,25 90,175 370,175" fill="#eff6ff" stroke="#1e40af" stroke-width="2"/>
      <line x1="160" y1="100" x2="300" y2="100" stroke="#dc2626" stroke-width="2.2"/>
      
      <text x="230" y="20" font-size="13" font-weight="bold" fill="#1e3a8a" text-anchor="middle">A</text>
      <text x="75" y="185" font-size="13" font-weight="bold" fill="#1e3a8a">B</text>
      <text x="380" y="185" font-size="13" font-weight="bold" fill="#1e3a8a">C</text>
      <text x="142" y="98" font-size="13" font-weight="bold" fill="#b91c1c">M</text>
      <text x="310" y="98" font-size="13" font-weight="bold" fill="#b91c1c">N</text>
      <text x="230" y="192" font-size="11.5" font-weight="bold" fill="#475569" text-anchor="middle">MN // BC (Định lí Thales)</text>
    </svg>`;
  },

  /**
   * Tam giác vuông và đường cao
   */
  svgRightTriangleWithAltitude() {
    return `<svg class="math-svg" viewBox="0 0 460 200" width="100%" role="img" aria-label="Tam giác vuông">
      <rect width="460" height="200" rx="10" fill="#f1f5f9"/>
      <polygon points="180,35 80,165 380,165" fill="#f0fdf4" stroke="#15803d" stroke-width="2"/>
      <line x1="180" y1="35" x2="180" y2="165" stroke="#dc2626" stroke-width="1.8" stroke-dasharray="4 3"/>
      <rect x="180" y="152" width="13" height="13" fill="none" stroke="#dc2626" stroke-width="1.5"/>

      <text x="180" y="28" font-size="13" font-weight="bold" fill="#14532d" text-anchor="middle">A</text>
      <text x="65" y="175" font-size="13" font-weight="bold" fill="#14532d">B</text>
      <text x="390" y="175" font-size="13" font-weight="bold" fill="#14532d">C</text>
      <text x="180" y="185" font-size="12" font-weight="bold" fill="#b91c1c" text-anchor="middle">H</text>
    </svg>`;
  },

  /**
   * Hai tam giác đồng dạng
   */
  svgSimilarTriangles() {
    return `<svg class="math-svg" viewBox="0 0 460 180" width="100%" role="img" aria-label="Tam giác đồng dạng">
      <rect width="460" height="180" rx="10" fill="#f1f5f9"/>
      <polygon points="140,25 45,150 235,150" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>
      <polygon points="350,60 285,150 415,150" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>
      <text x="140" y="20" font-size="13" font-weight="bold" fill="#1e40af" text-anchor="middle">A</text>
      <text x="350" y="52" font-size="13" font-weight="bold" fill="#b45309" text-anchor="middle">A'</text>
      <text x="230" y="170" font-size="11.5" font-weight="bold" fill="#475569" text-anchor="middle">ΔABC ∼ ΔA'B'C'</text>
    </svg>`;
  },

  /**
   * Đường tròn và góc nội tiếp
   */
  svgCircleAngle() {
    return `<svg class="math-svg" viewBox="0 0 460 200" width="100%" role="img" aria-label="Đường tròn">
      <rect width="460" height="200" rx="10" fill="#f1f5f9"/>
      <circle cx="230" cy="105" r="70" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>
      <circle cx="230" cy="105" r="3" fill="#0369a1"/>
      <text x="230" y="125" font-size="12" font-weight="bold" fill="#0369a1" text-anchor="middle">O</text>
      <polygon points="230,35 180,155 280,155" fill="none" stroke="#1e293b" stroke-width="1.8"/>
      <text x="230" y="28" font-size="12" font-weight="bold">A</text>
      <text x="168" y="168" font-size="12" font-weight="bold">B</text>
      <text x="288" y="168" font-size="12" font-weight="bold">C</text>
    </svg>`;
  },

  /**
   * Lăng trụ đứng tam giác
   */
  svgPrism3D() {
    return `<svg class="math-svg" viewBox="0 0 460 200" width="100%" role="img" aria-label="Hình lăng trụ đứng">
      <rect width="460" height="200" rx="10" fill="#f1f5f9"/>
      <polygon points="180,35 280,35 230,70" fill="#e0e7ff" stroke="#4338ca" stroke-width="1.8"/>
      <line x1="180" y1="35" x2="180" y2="145" stroke="#4338ca" stroke-width="1.8"/>
      <line x1="280" y1="35" x2="280" y2="145" stroke="#4338ca" stroke-width="1.8"/>
      <line x1="230" y1="70" x2="230" y2="180" stroke="#4338ca" stroke-width="1.8"/>
      <polygon points="180,145 280,145 230,180" fill="#c7d2fe" stroke="#4338ca" stroke-width="1.8"/>
      <text x="230" y="194" font-size="11.5" font-weight="bold" fill="#3730a3" text-anchor="middle">Hình lăng trụ đứng tam giác</text>
    </svg>`;
  },

  /**
   * Trục số bất phương trình
   */
  svgNumberLineInequality(val = 3, operator = '>=') {
    const w = 460, h = 90, ox = 230, oy = 50, scale = 36;
    const px = ox + val * scale;

    return `<svg class="math-svg" viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="Trục số">
      <rect width="${w}" height="${h}" rx="8" fill="#f1f5f9"/>
      <line x1="30" y1="${oy}" x2="${w - 30}" y2="${oy}" stroke="#1e293b" stroke-width="2"/>
      <line x1="${ox}" y1="${oy - 6}" x2="${ox}" y2="${oy + 6}" stroke="#64748b" stroke-width="1.5"/>
      <text x="${ox}" y="${oy + 22}" font-size="12" font-weight="bold" fill="#475569" text-anchor="middle">0</text>
      <line x1="${px}" y1="${oy - 6}" x2="${px}" y2="${oy + 6}" stroke="#2563eb" stroke-width="2"/>
      <text x="${px}" y="${oy + 22}" font-size="13" font-weight="bold" fill="#1d4ed8" text-anchor="middle">${val}</text>
      <line x1="35" y1="${oy - 8}" x2="${px - 1}" y2="${oy + 8}" stroke="#ef4444" stroke-width="2" stroke-dasharray="5 4"/>
      <text x="${px}" y="${oy + 5}" font-size="18" font-weight="bold" fill="#2563eb" text-anchor="middle">[</text>
      <text x="${w / 2}" y="20" font-size="11.5" font-weight="bold" fill="#0f172a" text-anchor="middle">Tập nghiệm: x ≥ ${val}</text>
    </svg>`;
  }
};

export default svgCap2;

// Hai mô hình lớp 6: khoảng chia và các phần bằng nhau có tọa độ chính xác.
export function svgGrade6NumberLine() {
  let body = '<path d="M 35 65 H 520 M 512 60 L 520 65 L 512 70" fill="none" stroke="#1e40af" stroke-width="2"/>';
  for (let value = -6; value <= 4; value += 2) {
    const x = 60 + (value + 6) * 40;
    body += '<path data-value="'+value+'" d="M '+x+' 59 V 71" stroke="#1e40af" stroke-width="2"/>';
    if (value !== -4) body += '<text x="'+x+'" y="96" text-anchor="middle">'+value+'</text>';
  }
  body += '<circle cx="140" cy="65" r="4" fill="#b91c1c"/><text x="140" y="42" text-anchor="middle" font-weight="bold">M</text>';
  return '<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" viewBox="0 0 560 120" width="100%" role="img" aria-label="Trục số có vạch chia đều, từ âm sáu đến bốn; M ở vạch kế âm sáu"><g font-family="Arial, sans-serif" font-size="17" fill="#0f172a">'+body+'</g></svg>';
}

export function svgGrade6FractionBar() {
  let body = '<text x="280" y="25" text-anchor="middle">Cả quyển sách</text>';
  for (let i = 0; i < 5; i++) body += '<rect data-part="'+(i+1)+'" x="'+(55+i*90)+'" y="46" width="90" height="48" fill="'+(i<2?'#bfdbfe':'#fff')+'" stroke="#1e40af" stroke-width="1.5"/>';
  body += '<path d="M 55 104 V 113 H 235 V 104 M 235 125 V 134 H 505 V 125" fill="none" stroke="#1e40af"/>';
  body += '<text x="145" y="137" text-anchor="middle">Đã đọc</text><text x="370" y="160" text-anchor="middle">54 trang còn lại</text>';
  return '<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" viewBox="0 0 560 185" width="100%" role="img" aria-label="Sách chia năm phần bằng nhau; hai phần đã đọc, ba phần còn lại gồm 54 trang"><g font-family="Arial, sans-serif" font-size="17" fill="#0f172a">'+body+'</g></svg>';
}

const svgText = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chartColors = ['#2563eb','#f59e0b','#10b981','#a855f7','#ef4444'];
function chartWrap(body,title,width=560,height=340){
  return '<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" viewBox="0 0 '+width+' '+height+'" width="100%" role="img" aria-label="'+svgText(title)+'"><g font-family="Arial, sans-serif" font-size="16" fill="#0f172a">'+body+'</g></svg>';
}
export function svgLineChart({labels,values,title,unit=''}){
  if(labels.length!==values.length || values.length<2 || values.some(v=>!Number.isFinite(v)||v<0))throw new Error('Dữ liệu biểu đồ đoạn thẳng không hợp lệ');
  const max=Math.max(10,Math.ceil(Math.max(...values)/10)*10);
  const x=i=>60+i*460/(values.length-1),y=v=>275-v*210/max;
  let body='<text x="280" y="25" text-anchor="middle" font-weight="bold">'+svgText(title)+'</text>';
  for(let i=0;i<=5;i++){
    const v=max*i/5,py=y(v);
    body+='<path d="M 60 '+py+' H 520" stroke="#cbd5e1"/><text x="48" y="'+(py+5)+'" text-anchor="end">'+v+'</text>';
  }
  body+='<text x="60" y="51">'+svgText(unit)+'</text><path d="M 60 65 V 275 H 525" fill="none" stroke="#334155"/>';
  body+='<polyline points="'+values.map((v,i)=>x(i)+','+y(v)).join(' ')+'" fill="none" stroke="#2563eb" stroke-width="2.5"/>';
  values.forEach((v,i)=>{
    body+='<circle data-label="'+svgText(labels[i])+'" data-value="'+v+'" cx="'+x(i)+'" cy="'+y(v)+'" r="4" fill="#2563eb"/>';
    body+='<text x="'+x(i)+'" y="'+(y(v)-12)+'" text-anchor="middle">'+v+'</text><text x="'+x(i)+'" y="304" text-anchor="middle">'+svgText(labels[i])+'</text>';
  });
  return chartWrap(body,title);
}
export function svgPieChart({labels,values,title,display='percent'}){
  const total=values.reduce((s,v)=>s+v,0);
  if(labels.length!==values.length||values.length<2||total<=0||values.some(v=>!Number.isFinite(v)||v<=0))throw new Error('Dữ liệu biểu đồ quạt không hợp lệ');
  const cx=155,cy=180,r=105,point=(d,rr=r)=>[cx+rr*Math.cos(d*Math.PI/180),cy+rr*Math.sin(d*Math.PI/180)];
  let start=-90,body='<text x="280" y="26" text-anchor="middle" font-weight="bold">'+svgText(title)+'</text>';
  values.forEach((v,i)=>{
    const sweep=360*v/total,end=start+sweep,a=point(start),b=point(end),mid=point(start+sweep/2,72),color=chartColors[i%chartColors.length];
    body+='<path data-label="'+svgText(labels[i])+'" data-count="'+v+'" data-total="'+total+'" data-start="'+start+'" data-sweep="'+sweep+'" d="M '+cx+' '+cy+' L '+a.join(' ')+' A '+r+' '+r+' 0 '+(sweep>180?1:0)+' 1 '+b.join(' ')+' Z" fill="'+color+'" stroke="#fff" stroke-width="1.5"/>';
    if(display!=='none'){
      const value=display==='angle'?Number(sweep.toFixed(2))+'°':Number((100*v/total).toFixed(2))+'%';
      body+='<text x="'+mid[0]+'" y="'+mid[1]+'" text-anchor="middle" dominant-baseline="middle" fill="#fff" font-weight="bold" stroke="#334155" stroke-width="0.5" paint-order="stroke">'+value+'</text>';
    }
    body+='<rect x="300" y="'+(90+i*48)+'" width="18" height="18" fill="'+color+'"/><text x="330" y="'+(105+i*48)+'">'+svgText(labels[i])+'</text>';
    start=end;
  });
  return chartWrap(body,title);
}
export function svgPrismModel({base,height,title,edgeLabels=[],heightLabel=String(height),open=false}){
  if(height<=0||base.length<3)throw new Error('Lăng trụ không hợp lệ');
  const project=(p,z)=>[(p[0]-p[1])*Math.sqrt(3)/2,(p[0]+p[1])/2-z];
  const raw=[...base.map(p=>project(p,0)),...base.map(p=>project(p,height))],n=base.length;
  const xs=raw.map(p=>p[0]),ys=raw.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  const scale=Math.min(370/(maxX-minX),220/(maxY-minY));
  const pts=raw.map(([x,y])=>[(x-(minX+maxX)/2)*scale+270,(y-(minY+maxY)/2)*scale+180]);
  const poly=(indices,fill)=>'<polygon points="'+indices.map(i=>pts[i].join(',')).join(' ')+'" fill="'+fill+'"/>';
  // Phép chiếu trục đo nhìn từ phía x,y,z dương; đáy khai báo ngược chiều kim đồng hồ.
  const visible=base.map((p,i)=>{const q=base[(i+1)%n];return q[1]-p[1]-(q[0]-p[0])>0;});
  const line=(i,j,hidden=false)=>'<path d="M '+pts[i].join(' ')+' L '+pts[j].join(' ')+'" fill="none" stroke="#1e40af" stroke-width="1.8"'+(hidden?' stroke-dasharray="5 4"':'')+'/>';
  let body='<text x="280" y="24" text-anchor="middle" font-weight="bold">'+svgText(title)+'</text>';
  body+=poly(Array.from({length:n},(_,i)=>i),'#dbeafe');
  if(open)for(let i=0;i<n;i++)if(!visible[i])body+=poly([i,(i+1)%n,(i+1)%n+n,i+n],'#f8fafc');
  for(let i=0;i<n;i++)if(visible[i])body+=poly([i,(i+1)%n,(i+1)%n+n,i+n],i%2?'#eff6ff':'#e0e7ff');
  if(!open)body+=poly(Array.from({length:n},(_,i)=>i+n),'#bfdbfe');
  for(let i=0;i<n;i++){
    body+=line(i,(i+1)%n,!visible[i]);
    body+=line(i,i+n,!(visible[i]||visible[(i+n-1)%n]));
    body+=line(i+n,(i+1)%n+n);
  }
  const centre=pts.slice(n).reduce((p,q)=>[p[0]+q[0]/n,p[1]+q[1]/n],[0,0]);
  for(const {edge,text} of edgeLabels){
    const a=pts[edge+n],b=pts[(edge+1)%n+n],mid=[(a[0]+b[0])/2,(a[1]+b[1])/2];
    const dist=Math.hypot(mid[0]-centre[0],mid[1]-centre[1]);
    body+='<text x="'+(mid[0]+20*(mid[0]-centre[0])/dist)+'" y="'+(mid[1]+20*(mid[1]-centre[1])/dist)+'" text-anchor="middle" dominant-baseline="middle" stroke="#fff" stroke-width="4" paint-order="stroke">'+svgText(text)+'</text>';
  }
  const right=pts.slice(0,n).reduce((k,p,i)=>p[0]>pts[k][0]?i:k,0),a=pts[right],b=pts[right+n];
  body+='<text x="'+(a[0]+24)+'" y="'+((a[1]+b[1])/2)+'" stroke="#fff" stroke-width="4" paint-order="stroke">'+svgText(heightLabel)+'</text>';
  return chartWrap(body,title);
}
export function svgMeasurementRuler(){
  const px=v=>50+45*v;let body='<text x="280" y="24" text-anchor="middle">Đọc hai đầu cạnh trên thước (cm)</text>';
  body+='<path d="M 50 125 H 500" stroke="#334155"/>';
  for(let i=0;i<=50;i++){const v=i/5,x=px(v);
    body+='<path d="M '+x+' 125 V '+(i%5===0?108:117)+'" stroke="#64748b"/>';
    if(i%5===0)body+='<text x="'+x+'" y="148" text-anchor="middle">'+v+'</text>';
  }
  body+='<path d="M '+px(2.4)+' 62 H '+px(8.4)+'" stroke="#2563eb" stroke-width="5"/>';
  for(const v of [2.4,8.4])body+='<path d="M '+px(v)+' 62 V 125" stroke="#ef4444" stroke-dasharray="4 3"/><text x="'+px(v)+'" y="48" text-anchor="middle">'+String(v).replace('.',',')+'</text>';
  return chartWrap(body,'Hai đầu cạnh ở vạch 2,4 cm và 8,4 cm',560,175);
}


/** Thước hai thang; tia gốc về bên phải, số đo thật theo góc lượng giác. */
export function svgProtractor(degrees = 140) {
  if (!Number.isFinite(degrees) || degrees <= 0 || degrees >= 180) throw new Error('Góc đo không hợp lệ');
  const ox = 280, oy = 220;
  const at = (d, r) => [ox + r * Math.cos(d * Math.PI / 180), oy - r * Math.sin(d * Math.PI / 180)];
  const pair = p => p.map(x => Number(x.toFixed(4))).join(' ');
  const line = (p,q,color='#1e40af',width=1) => '<path d="M '+pair(p)+' L '+pair(q)+'" fill="none" stroke="'+color+'" stroke-width="'+width+'"/>';
  const text = (p,s,color='#0f172a',size=15) => '<text x="'+p[0]+'" y="'+p[1]+'" fill="'+color+'" font-size="'+size+'" text-anchor="middle" dominant-baseline="middle" stroke="#fff" stroke-width="3" paint-order="stroke">'+s+'</text>';
  let body='<path d="M 110 220 A 170 170 0 0 1 450 220" fill="#eff6ff" stroke="#93c5fd"/>';
  for(let d=0;d<=180;d+=10){
    body+=line(at(d,d%20===0?157:164),at(d,170),'#64748b');
    if(d%20===0 || d===90){
      body+=text(at(d,190),d,'#1e40af');
      body+=text(at(d,137),180-d,'#64748b');
    }
  }
  body+=line([65,oy],[505,oy],'#1e40af',2);
  body+=line([ox,oy],at(degrees,210),'#b91c1c',2);
  body+=text([ox,oy+23],'O')+text([505,oy+23],'A')+text(at(degrees,231),'B','#b91c1c',18);
  return '<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" viewBox="0 0 560 270" width="100%" role="img" aria-label="Thước đo hai thang, tia OA hướng sang phải, tia OB ở vạch 140 độ"><g font-family="Arial, sans-serif">'+body+'</g></svg>';
}


// Trục số tuyến tính: cùng một đơn vị tọa độ cho các vạch và điểm đánh dấu.
export function svgRealNumberLine({ min = -2, max = 2, step = 0.5, value = -1.5 } = {}) {
  const count = (max - min) / step;
  if (![min, max, step, value].every(Number.isFinite) || step <= 0 || max <= min ||
      value < min || value > max || !Number.isInteger(count) || count > 100) {
    throw new Error('Thông số trục số không hợp lệ');
  }
  const px = x => 50 + (x - min) * 90;
  const width = 100 + (max - min) * 90;
  const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  let body = '<line x1="25" y1="65" x2="' + (width - 20) + '" y2="65" stroke="#1e40af" stroke-width="2"/>' +
    '<path d="M ' + (width - 28) + ' 60 L ' + (width - 20) + ' 65 L ' + (width - 28) + ' 70" fill="none" stroke="#1e40af" stroke-width="2"/>';
  for (let i = 0; i <= count; i++) {
    const x = min + i * step, pos = px(x);
    body += '<line data-value="' + esc(x) + '" x1="' + pos + '" y1="59" x2="' + pos + '" y2="71" stroke="#1e40af" stroke-width="1.5"/>';
    if (Number.isInteger(x)) body += '<text x="' + pos + '" y="94" text-anchor="middle" font-size="16">' + esc(x) + '</text>';
  }
  body += '<circle cx="' + px(value) + '" cy="65" r="4" fill="#b91c1c"/>' +
    '<text x="' + px(value) + '" y="40" text-anchor="middle" font-size="18" font-weight="bold" fill="#b91c1c">M</text>';
  return '<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" viewBox="0 0 ' + width + ' 115" width="100%" role="img" aria-label="Trục số có các vạch cách đều; M nằm chính giữa âm hai và âm một"><g font-family="Arial, sans-serif" fill="#0f172a">' + body + '</g></svg>';
}


/**
 * Hình lớp 7 dùng tọa độ toán học; cùng một hệ số cho hai trục.
 * Ký hiệu được kiểm tra theo tọa độ trước khi xuất SVG.
 */
export function svgGeometry(config) {
  const { points, edges, equal = [], angles = [], right = [], edgeLabels = [], offsets = {}, labels = {}, title = 'Hình học lớp 7' } = config;
  const esc = text => String(text).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const near = (a, b) => Math.abs(a - b) <= 1e-7 * Math.max(1, Math.abs(a), Math.abs(b));
  const length = (a, b) => Math.hypot(points[a][0] - points[b][0], points[a][1] - points[b][1]);
  const values = Object.values(points);
  if (values.length < 3 || values.some(p => p.length !== 2 || p.some(v => !Number.isFinite(v)))) throw new Error('Tọa độ hình không hợp lệ');
  const xs = values.map(p => p[0]), ys = values.map(p => p[1]);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  if (near(maxX, minX) || near(maxY, minY)) throw new Error('Hình suy biến');
  const width = 560, height = 340, margin = 48;
  const scale = Math.min((width - 2 * margin) / (maxX - minX), (height - 2 * margin) / (maxY - minY));
  const project = name => [(points[name][0] - (minX + maxX) / 2) * scale + width / 2, height / 2 - (points[name][1] - (minY + maxY) / 2) * scale];
  const num = n => Number(n.toFixed(4));
  const line = (p, q, extra = '') => '<line x1="' + num(p[0]) + '" y1="' + num(p[1]) + '" x2="' + num(q[0]) + '" y2="' + num(q[1]) + '" ' + extra + '/>';
  const text = (p, value, extra = '') => '<text x="' + num(p[0]) + '" y="' + num(p[1]) + '" text-anchor="middle" dominant-baseline="middle" font-family="Arial, sans-serif" font-size="17" fill="#0f172a" stroke="#fff" stroke-width="4" paint-order="stroke" ' + extra + '>' + esc(value) + '</text>';
  let body = '';
  for (const [a, b] of edges) {
    if (near(length(a, b), 0)) throw new Error('Đoạn thẳng suy biến');
    body += line(project(a), project(b), 'stroke="#1e40af" stroke-width="2" data-edge="' + esc(a + '-' + b) + '"');
  }
  equal.forEach((group, index) => {
    const expected = length(group[0][0], group[0][1]);
    group.forEach(([a, b, at = 0.5]) => {
      if (!near(length(a, b), expected)) throw new Error('Ký hiệu bằng nhau sai: ' + a + b);
      const p = project(a), q = project(b), len = Math.hypot(q[0] - p[0], q[1] - p[1]);
      const u = [(q[0] - p[0]) / len, (q[1] - p[1]) / len], v = [-u[1], u[0]];
      for (let i = 0; i <= index; i++) {
        const center = [p[0] + at * (q[0] - p[0]) + (i - index / 2) * 6 * u[0], p[1] + at * (q[1] - p[1]) + (i - index / 2) * 6 * u[1]];
        body += line([center[0] - 5 * v[0], center[1] - 5 * v[1]], [center[0] + 5 * v[0], center[1] + 5 * v[1]], 'stroke="#b91c1c" stroke-width="2" data-equal="' + index + '"');
      }
    });
  });
  for (const { at, from, to, value, radius = 24, labelRadius = 42 } of angles) {
    const p = project(at), a = project(from), b = project(to);
    const start = Math.atan2(a[1] - p[1], a[0] - p[0]);
    let delta = Math.atan2(b[1] - p[1], b[0] - p[0]) - start;
    while (delta > Math.PI) delta -= 2 * Math.PI;
    while (delta < -Math.PI) delta += 2 * Math.PI;
    if (typeof value === 'number' && !near(Math.abs(delta) * 180 / Math.PI, value)) throw new Error('Số đo góc không khớp: ' + at);
    const on = (theta, r) => [p[0] + r * Math.cos(theta), p[1] + r * Math.sin(theta)];
    const s = on(start, radius), e = on(start + delta, radius);
    body += '<path d="M ' + s.map(num).join(' ') + ' A ' + radius + ' ' + radius + ' 0 0 ' + (delta > 0 ? 1 : 0) + ' ' + e.map(num).join(' ') + '" fill="none" stroke="#b91c1c" stroke-width="1.5"/>';
    if (value !== undefined) body += text(on(start + delta / 2, labelRadius), typeof value === 'number' ? value + '°' : value);
  }
  for (const [from, at, to] of right) {
    const p = project(at), a = project(from), b = project(to);
    const la = Math.hypot(a[0] - p[0], a[1] - p[1]), lb = Math.hypot(b[0] - p[0], b[1] - p[1]);
    const u = [(a[0] - p[0]) / la, (a[1] - p[1]) / la], v = [(b[0] - p[0]) / lb, (b[1] - p[1]) / lb];
    if (!near(u[0] * v[0] + u[1] * v[1], 0)) throw new Error('Ký hiệu vuông sai: ' + at);
    const a1 = [p[0] + 12 * u[0], p[1] + 12 * u[1]], b1 = [a1[0] + 12 * v[0], a1[1] + 12 * v[1]], c1 = [p[0] + 12 * v[0], p[1] + 12 * v[1]];
    body += '<polyline points="' + [a1, b1, c1].map(v => v.map(num).join(',')).join(' ') + '" fill="none" stroke="#b91c1c" stroke-width="1.5"/>';
  }
  for (const { a, b, value, text: label, offset = 16, at = 0.5 } of edgeLabels) {
    if (value !== undefined && !near(length(a, b), value)) throw new Error('Độ dài không khớp: ' + a + b);
    const p = project(a), q = project(b), len = Math.hypot(q[0] - p[0], q[1] - p[1]);
    body += text([p[0] + at * (q[0] - p[0]) - offset * (q[1] - p[1]) / len, p[1] + at * (q[1] - p[1]) + offset * (q[0] - p[0]) / len], label);
  }
  for (const name of Object.keys(points)) {
    const p = project(name), [dx, dy] = offsets[name] || [0, -17];
    body += '<circle cx="' + num(p[0]) + '" cy="' + num(p[1]) + '" r="2.5" fill="#1e40af" data-point="' + esc(name) + '"/>';
    if (labels[name] !== '') body += text([p[0] + dx, p[1] + dy], labels[name] ?? name, 'font-weight="bold"');
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" viewBox="0 0 560 340" width="100%" role="img" aria-label="' + esc(title) + '">' + body + '</svg>';
}

// Hình trực quan lớp 6: giữ tọa độ gốc, không làm tròn từng đỉnh.
// Các mảnh bằng nhau dùng cùng kích thước; phép dời chỉ qua transform SVG.
export function svgGrade6Visual(question) {
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const blue = '#bfdbfe', orange = '#fed7aa', ink = '#1e40af';
  const text = (x,y,s,extra='') => `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle" font-size="16" fill="#0f172a" ${extra}>${esc(s)}</text>`;
  const line = (x1,y1,x2,y2,extra='') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${extra.includes('stroke=')?'':`stroke="${ink}"`} ${extra.includes('stroke-width=')?'':'stroke-width="2"'} ${extra}/>`;
  const poly = (id,p,fill=blue,extra='') => `<polygon data-shape="${id}" points="${p.map(v=>v.join(',')).join(' ')}" fill="${fill}" stroke="${ink}" ${extra.includes('stroke-width=')?'':'stroke-width="2"'} ${extra}/>`;
  const rect = (id,x,y,w,h,fill=blue) => `<rect data-cell="${id}" x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" stroke="${ink}" stroke-width="1.5"/>`;
  const group = (x,y,body) => `<g transform="translate(${x} ${y})">${body}</g>`;
  const dot = (x,y,name,dx=0,dy=-17) => `<circle cx="${x}" cy="${y}" r="3" fill="${ink}"/>`+text(x+dx,y+dy,name);
  const hex = s => [[s,0],[s/2,s*Math.sqrt(3)/2],[-s/2,s*Math.sqrt(3)/2],[-s,0],[-s/2,-s*Math.sqrt(3)/2],[s/2,-s*Math.sqrt(3)/2]];
  const grid = (n,sz,x,y,filled,numbered=false) => {
    let b='';
    for(let r=0;r<n;r++)for(let c=0;c<n;c++) {
      b+=rect(`${r+1}-${c+1}`,x+c*sz,y+r*sz,sz,sz,filled.some(v=>v[0]===r&&v[1]===c)?blue:'#fff');
      if(numbered)b+=text(x+(c+.5)*sz,y+(r+.5)*sz,r*n+c+1);
    }
    if(!numbered)for(let i=0;i<n;i++)b+=text(x+(i+.5)*sz,y-15,i+1)+text(x-17,y+(i+.5)*sz,i+1);
    return b;
  };
  let body='',height=280;
  switch(question) {
    case 1: {
      body=group(70,130,poly('triangle',[[-42,30],[42,30],[0,30-42*Math.sqrt(3)]]))+text(70,215,'I');
      body+=group(210,125,poly('hexagon',hex(48)))+text(210,215,'II');
      body+=group(350,125,poly('rectangle',[[-48,-30],[48,-30],[48,30],[-48,30]]))+text(350,215,'III');
      body+=group(490,125,poly('pentagon',[[-45,15],[-28,-38],[28,-38],[45,15],[0,48]]))+text(490,215,'IV');
      break;
    }
    case 2: {
      const p=[[0,-75],[100,0],[0,75],[-100,0]];
      let b=poly('rhombus',p)+text(0,-96,'A')+text(122,0,'B')+text(0,97,'C')+text(-122,0,'D');
      p.forEach((v,i)=>{const w=p[(i+1)%4],mx=(v[0]+w[0])/2,my=(v[1]+w[1])/2; b+=line(mx-(w[1]-v[1])/25,my+(w[0]-v[0])/25,mx+(w[1]-v[1])/25,my-(w[0]-v[0])/25,'data-equal="rhombus" stroke="#b45309"');});
      body=group(280,140,b);break;
    }
    case 3:
      body=group(280,140,poly('rectangle',[[-120,-60],[120,-60],[120,60],[-120,60]])+line(-140,0,140,0,'stroke-dasharray="6 4"')+text(157,0,'d₁')+line(-120,-60,120,60,'stroke-dasharray="6 4" stroke="#b45309"')+text(126,80,'d₂'));break;
    case 4:
      body=group(280,140,poly('parallelogram',[[-120,-60],[60,-60],[120,60],[-60,60]])+line(-120,-60,120,60,'stroke-dasharray="5 4"')+line(60,-60,-60,60,'stroke-dasharray="5 4"')+dot(0,0,'O',15,-13)+text(-130,-80,'A')+text(70,-80,'B')+text(130,80,'C')+text(-70,80,'D'));break;
    case 5:
      body=grid(4,46,188,40,[[0,0],[1,0],[2,1]])+line(280,12,280,243,'stroke="#b45309" stroke-dasharray="6 4"')+text(280,259,'d');break;
    case 6: {
      for(let k=0;k<=4;k++)body+=line(160+40*k,65,160+40*k,225,'stroke="#cbd5e1" stroke-width="1"')+line(160,65+40*k,320,65+40*k,'stroke="#cbd5e1" stroke-width="1"');
      body+=line(160,225,320,225)+line(160,225,160,105);
      body+=dot(160,225,'A',-16,8)+dot(320,225,'B',17,8)+dot(160,105,'D',-17,0)+dot(280,65,'P')+dot(320,145,'Q',18,0)+dot(280,105,'R',-16,0)+dot(320,105,'S',18,0);break;
    }
    case 7: {
      const p=hex(105);let b='';
      p.forEach((v,i)=>b+=poly('sector-'+i,[[0,0],v,p[(i+1)%6]],i<2?'#fff':blue));
      body=group(280,140,b);break;
    }
    case 8: {
      const sz=54;
      for(const [r,c] of [[0,0],[0,1],[1,0],[1,1],[1,2]])body+=rect(`${r}-${c}`,190+c*sz,75+r*sz,sz,sz);
      body+=poly('outline',[[190,75],[298,75],[298,129],[352,129],[352,183],[190,183]],'none','stroke-width="3"');break;
    }
    case 9: {
      let b=poly('trapezoid',[[-60,-40],[60,-40],[120,40],[-120,40]]);
      b+=line(-60,-40,-60,40,'stroke-dasharray="5 4"')+line(60,-40,60,40,'stroke-dasharray="5 4"');
      b+=line(-60,30,-50,30)+line(-50,30,-50,40)+line(60,30,70,30)+line(70,30,70,40);
      b+=text(-70,-61,'A')+text(70,-61,'B')+text(-134,50,'D')+text(134,50,'C')+text(-60,60,'H')+text(60,60,'K');
      b+=text(0,-62,'6 cm')+text(0,24,'6 cm')+text(0,85,'12 cm');
      body=group(280,130,b);break;
    }
    case 10: {
      for(const [r,c] of [[0,0],[1,0],[1,1]])body+=rect(`piece-${r}-${c}`,55+c*60,75+r*60,60,60);
      body+='<circle cx="85" cy="105" r="6" fill="#dc2626"/>'+text(115,225,'Mảnh cần đặt');
      body+=line(205,130,265,130)+line(255,123,265,130)+line(255,137,265,130);
      for(let r=0;r<2;r++)for(let c=0;c<3;c++)body+=rect(`target-${r}-${c}`,300+c*60,75+r*60,60,60,[[0,0],[1,0],[1,1]].some(v=>v[0]===r&&v[1]===c)?blue:'#fff');
      body+=text(390,105,'A')+text(450,105,'B')+text(450,165,'C')+text(390,225,'Hình cần ghép');break;
    }
    case 11:
      body=group(280,140,poly('hexagon',hex(110)));break;
    case 12:
      body=grid(5,38,185,45,[[0,1],[1,0],[2,2]])+line(280,13,280,249,'stroke="#b45309" stroke-dasharray="6 4"')+text(280,265,'d')+line(151,140,400,140,'stroke="#b45309" stroke-dasharray="6 4"')+text(417,140,'e');break;
    case 13:
      body=grid(4,45,190,50,[[0,0],[1,3],[2,2]],true)+dot(280,140,'O',12,-10);break;
    case 14: {
      const cut=[[0,72],[48,72],[48,0]],rest=[[48,0],[192,0],[144,72],[48,72]];
      body=group(30,70,poly('cut-before',cut,orange)+poly('rest-before',rest))+text(130,195,'Hình ban đầu');
      body+=line(245,106,283,106)+line(273,99,283,106)+line(273,113,283,106);
      body+=group(315,70,poly('rest-after',[[0,0],[144,0],[96,72],[0,72]])+poly('cut-after',[[96,72],[144,72],[144,0]],orange))+text(390,195,'Sau khi ghép');break;
    }
    case 15: {
      const m=[[0,-90],[90,0],[0,90],[-90,0]],corners=[[-90,-90],[90,-90],[90,90],[-90,90]];
      let b=poly('square',corners,'#fff');
      corners.forEach((p,i)=>b+=poly('corner-'+i,[p,m[i],m[(i+3)%4]],orange));
      b+=poly('diamond',m,'#eff6ff','stroke-dasharray="6 4"');
      for(const p of m)b+=line(0,0,p[0],p[1],'stroke="#93c5fd" stroke-width="1"');
      b+=dot(0,0,'O',13,-12);
      m.forEach((p,i)=>b+=text(p[0]+[0,17,0,-17][i],p[1]+[-17,0,17,0][i],['M','N','P','Q'][i]));
      body=group(280,140,b);break;
    }
    default: throw new Error('Không có hình trực quan lớp 6 cho câu '+question);
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" data-grade6-visual="${question}" viewBox="0 0 560 ${height}" width="100%" role="img" aria-label="Hình trực quan lớp 6, câu ${question}" font-family="Arial, sans-serif">${body}</svg>`;
}


// Đoạn thẳng và diện tích lớp 6: một tỉ lệ cho cả hai trục, không làm tròn đỉnh.
function grade6DrawingKit() {
  const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const text = (x,y,s,size=16) => `<text x="${x}" y="${y}" font-size="${size}" text-anchor="middle" dominant-baseline="middle" fill="#0f172a" stroke="#fff" stroke-width="3" paint-order="stroke">${esc(s)}</text>`;
  const line = (x1,y1,x2,y2,extra='') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#1e40af" stroke-width="2" ${extra}/>`;
  const poly = (id,p,fill='#bfdbfe',extra='') => `<polygon data-shape="${id}" points="${p.map(v=>v.join(',')).join(' ')}" fill="${fill}" stroke="#1e40af" stroke-width="2" ${extra}/>`;
  const group = (x,y,body) => `<g transform="translate(${x} ${y})">${body}</g>`;
  const point = (x,y,name,dx=0,dy=-18) => `<circle data-point="${name}" cx="${x}" cy="${y}" r="3" fill="#1e40af"/>`+text(x+dx,y+dy,name);
  const dim = (x1,y1,x2,y2,label) => line(x1,y1,x2,y2,'data-dimension="'+esc(label)+'"')+(y1===y2?line(x1,y1-4,x1,y1+4)+line(x2,y2-4,x2,y2+4)+text((x1+x2)/2,y1+16,label):line(x1-4,y1,x1+4,y1)+line(x2-4,y2,x2+4,y2)+text(x1-24,(y1+y2)/2,label));
  const wrap = (body,name,height=300) => `<svg xmlns="http://www.w3.org/2000/svg" class="math-svg" data-grade6-drawing="${name}" viewBox="0 0 560 ${height}" width="100%" role="img" aria-label="${esc(name)}" font-family="Arial, sans-serif">${body}</svg>`;
  return {text,line,poly,group,point,dim,wrap};
}

function grade6TwoScaleAngle(question) {
  const {text,line,wrap}=grade6DrawingKit(),ox=280,oy=240;
  const p=(d,r)=>[ox+r*Math.cos(d*Math.PI/180),oy-r*Math.sin(d*Math.PI/180)];
  let b='<path d="M 105 240 A 175 175 0 0 1 455 240" fill="#eff6ff" stroke="#93c5fd"/>';
  let tickLabels='';
  for(let d=0;d<=180;d+=10){
    const a=p(d,d%30===0?160:168),z=p(d,175);b+=line(...a,...z);
    if(d%30===0){const out=p(d,194),inside=p(d,139);tickLabels+=text(...out,d,13)+text(...inside,180-d,13);}
  }
  b+=line(65,oy,495,oy,'data-ray="baseline"')+line(ox,oy,...p(120,205),'data-ray="OB"');
  b+=tickLabels;
  b+=text(65,oy+22,'A')+text(ox,oy+22,'O')+text(...p(120,226),'B');
  return wrap(b,'Hình cơ bản lớp 6, câu '+question+': thước hai thang, OA hướng trái',300);
}

export function svgGrade6Basics(question) {
  const {text,line,poly,group,point,dim,wrap}=grade6DrawingKit();
  let b='';
  const chain=(positions,y=110)=>{
    let s=line(40,y,520,y);
    for(const [name,x] of Object.entries(positions))s+=point(x,y,name);
    return s;
  };
  switch(question){
    case 1:
      b=line(60,150,500,150)+point(150,150,'M')+point(350,150,'N')+point(250,80,'P')+text(490,130,'d');break;
    case 2:b=chain({A:100,C:220,B:430},150);break;
    case 3:{
      const ox=260,oy=220,d=120*Math.PI/180;
      b=line(ox,oy,470,oy,'data-ray="Ox"')+line(ox,oy,ox+190*Math.cos(d),oy-190*Math.sin(d),'data-ray="Oy"');
      b+='<path d="M 310 220 A 50 50 0 0 0 235 '+(220-25*Math.sqrt(3))+'" fill="none" stroke="#b45309"/>';
      b+=text(ox,oy+20,'O')+text(490,oy,'x')+text(ox+210*Math.cos(d),oy-210*Math.sin(d),'y')+text(310,145,'120°');break;
    }
    case 4:b=line(90,150,490,150)+line(480,144,490,150)+line(480,156,490,150)+point(90,150,'A')+point(220,150,'B')+point(400,150,'C');break;
    case 5:{
      const x=v=>60+50*v;b=line(60,160,460,160);
      for(let k=0;k<=16;k++){const xx=x(k/2);b+=line(xx,160,xx,k%2?151:145);if(k%2===0)b+=text(xx,182,k/2,14);}
      b+=line(x(1.5),100,x(6),100,'data-segment="AB"')+point(x(1.5),100,'A')+point(x(6),100,'B');
      b+=line(x(1.5),105,x(1.5),160,'stroke-dasharray="4 3"')+line(x(6),105,x(6),160,'stroke-dasharray="4 3"')+text(x(1.5),213,'1,5 cm')+text(x(6),213,'6 cm');break;
    }
    case 6:b=chain({A:80,P:130,M:255,B:430})+dim(80,160,430,160,'14 cm')+dim(80,210,130,210,'2 cm');break;
    case 7:return grade6TwoScaleAngle(question);
    case 8:b=chain({A:90,B:175,C:255,D:370,E:475},150);break;
    case 9:
      b=line(60,210,500,210)+line(100,210,250,70)+line(250,210,250,70)+line(450,210,250,70)+point(100,210,'A',0,20)+point(250,210,'B',0,20)+point(450,210,'C',0,20)+point(250,70,'D');break;
    case 10:
      b=line(60,170,500,170)+line(115,105,430,105,'data-segment="AB"')+point(115,105,'A')+point(272.5,105,'M')+point(430,105,'B');
      for(const [x,v] of [[115,'2 cm'],[272.5,'5,5 cm'],[430,'?']])b+=line(x,110,x,180,'stroke-dasharray="4 3"')+text(x,203,v);break;
    case 11:
      b=chain({A:70,B:160,C:310,D:460})+dim(70,158,460,158,'13 cm')+dim(70,215,160,215,'3 cm')+dim(310,215,460,215,'5 cm');break;
    case 12:
      b=chain({A:60,M:135,B:210,N:335,C:460})+dim(60,160,335,160,'11 cm')+dim(135,215,460,215,'13 cm');
      for(const x of [97.5,172.5])b+=line(x-4,103,x+4,117);
      for(const x of [272.5,397.5])b+=line(x-6,103,x+2,117)+line(x,103,x+8,117);break;
    case 13:{
      const x=[65,119,200,335,389,470],labels=['A','B','C','D','E','F'];
      b=chain(Object.fromEntries(labels.map((s,i)=>[s,x[i]])),140);
      for(let i=0;i<5;i++)b+=dim(x[i],190,x[i+1],190,[2,3,5,2,3][i]+' cm');break;
    }
    case 14:
      b=poly('paper',[[70,55],[490,55],[490,250],[70,250]],'#eff6ff')+line(120,155,440,155,'data-segment="AB"')+point(120,155,'A')+point(440,155,'B')+point(280,155,'M',16,-15)+line(280,45,280,258,'stroke-dasharray="6 4"')+text(280,280,'Nếp gấp');break;
    case 15:return grade6TwoScaleAngle(question);
    default:throw new Error('Không có hình cơ bản lớp 6 câu '+question);
  }
  return wrap(b,'Hình cơ bản lớp 6, câu '+question);
}

